478	static fetch_t* fetch_create(FeatureInstanceHandle feature,
479	    ft_context_ref ft_ctx, FtPromiseId pid, system_fetch_FetchPara* obj,
480	    const char* pkg, content_t* ct)
481	{
482	    fetch_t* fetch = new fetch_t;
483	    assert(fetch);
484	    fetch->ft_ctx = ft_ctx;
485	    fetch->feature = FeatureDupInstanceHandle(feature);
486	    fetch->pid = pid;
487	    fetch->response_type = get_response_tpye(obj->responseType);
488	    fetch->type = (fetch->response_type == Fetch::ResponseType::FILE)
489	        ? UV_DOWNLOAD
490	        : UV_REQUEST;
491	    if (fetch->type == UV_DOWNLOAD) {
492	        char* path = NULL;
493	        char* filename = basename((char*)obj->url);
494	
495	        if (strlen(filename) == strlen(obj->url)) {
496	            time_t cur_time = time(NULL);
497	            char time_buf[100];
498	            strftime(time_buf, sizeof(time_buf), "%Y%m%d %H%M%S",
499	                std::localtime(&cur_time));
500	            filename = time_buf;
501	        }
502	
503	        path = app_relative_to_absolute_path(pkg, filename);
504	
505	        if (path == NULL) {
506	            path = app_absolute_path_generator(pkg, "files", filename);
507	        }
508	
509	        if (path == NULL) {
510	            FETCH_ERROR("No memory!");
511	            return NULL;
512	        }
513	
514	        fetch->filename.assign(path);
515	        free((void*)path);
516	    }
517	
518	    fetch->request = NULL;
519	    fetch->content = ct;
520	    fetch->url = NULL;
521	    return fetch;
522	}
